macro_rules! FingerprintStyle {
    () => {
        # [doc = " Describes the contents of the fingerprint generated by a given query."] # [derive (Debug , PartialEq , Eq , Copy , Clone)] pub enum FingerprintStyle { # [doc = " The fingerprint is actually a DefPathHash."] DefPathHash , # [doc = " The fingerprint is actually a HirId."] HirId , # [doc = " Query key was `()` or equivalent, so fingerprint is just zero."] Unit , # [doc = " Some opaque hash."] Opaque , }
    };
}

